12: const START_LOG = [
13:   ['The Lastlight gate closes behind you. It does not open again.', 'daybreak'],
14:   ['Four survivors. One crawler. Nine hundred sixty miles to a rumor.', ''],
15:   ['Mara checks the welds. Imani checks the water. Dex checks the locks. Rook checks the horizon, then checks it again.', ''],
