19: export class Game {
20:   constructor() {
21:     this.S = null;
22:     this.phase = 'menu';
23:     this.pendingEvent = null;
24:     this.pendingArrival = null;
25:     this.lastResult = null;
26:   }
27: 
28:   /* ---------- lifecycle ---------- */
29: 
30:   newGame() {
31:     const crew = CREW_TEMPLATES.map((c) => ({
32:       id: c.id, name: c.name, role: c.role, initials: c.initials, tone: c.tone,
33:       trait: c.trait, perk: c.perk, health: c.health, status: 'ok', alive: true, cause: null,
34:     }));
35:     const stocks = {};
36:     for (const stop of ROUTE) stocks[stop.mile] = { ...stop.stock };
37:     this.S = {
38:       version: 1,
39:       day: 1, mile: 0,
40:       water: START.water, food: START.food, fuel: START.fuel, scrap: START.scrap, meds: START.meds,
41:       hull: START.hull, morale: START.morale,
42:       pace: 'steady', ration: 'half', weather: 'clear',
43:       party: crew, stocks,
44:       visited: [0], restedAt: [], rumors: {}, recentEvents: [],
45:       stats: { chores: 0, events: 0, miles: 0, scavenged: 0, damages: 0 },
46:       log: START_LOG.map(([text, kind]) => ({ day: 1, text, kind })),
47:       ended: null, dog: false,
48:       scrapEarned: 0, foodFound: 0,
49:     };
50:     this.phase = 'travel';
51:     this.pendingEvent = null;
52:     this.pendingArrival = null;
53:     return this.snapshot();
54:   }
55: 
56:   snapshot() {
57:     return {
58:       state: this.S, phase: this.phase,
59:       event: this.pendingEvent, arrival: this.pendingArrival, ended: this.S?.ended || null,
60:     };
61:   }
62: 
63:   save() {
64:     try { if (this.S) localStorage.setItem(SAVE_KEY, JSON.stringify(this.S)); } catch { /* storage may be unavailable */ }
65:   }
66: 
67:   hasSave() {
68:     try { return !!localStorage.getItem(SAVE_KEY); } catch { return false; }
69:   }
70: 
71:   peekSave() {
72:     try {
73:       const raw = localStorage.getItem(SAVE_KEY);
74:       if (!raw) return null;
75:       const S = JSON.parse(raw);
76:       if (!S || S.version !== 1 || S.ended) return null;
77:       return S;
78:     } catch { return null; }
79:   }
80: 
81:   load() {
82:     try {
83:       const raw = localStorage.getItem(SAVE_KEY);
84:       if (!raw) return null;
85:       const S = JSON.parse(raw);
86:       if (!S || !Array.isArray(S.party) || S.version !== 1) return null;
87:       this.S = S;
88:       this.phase = S.ended ? 'ended' : 'travel';
89:       const stop = ROUTE.find((r) => r.mile === S.mile);
90:       if (!S.ended && stop && stop.mile > 0 && stop.mile < 960) this.phase = 'arrival';
91:       this.pendingEvent = null;
92:       this.pendingArrival = null;
93:       return this.snapshot();
94:     } catch { return null; }
95:   }
96: 
97:   clearSave() {
98:     try { localStorage.removeItem(SAVE_KEY); } catch { /* ignore */ }
99:   }
100: 
101:   alive() { return this.S.party.filter((p) => p.alive); }
102:   aliveCount() { return this.alive().length; }
103:   hasTrait(id) { return this.S.party.some((p) => p.alive && p.id === id); }
104:   getStop(mile = this.S.mile) { return ROUTE.find((s) => s.mile === mile) || ROUTE[0]; }
105:   nextStop() { return ROUTE.find((s) => s.mile > this.S.mile) || null; }
106: 
107:   /* ---------- resources ---------- */
108: 
109:   log(text, kind = '') {
110:     this.S.log.push({ day: this.S.day, text, kind });
111:     if (this.S.log.length > 120) this.S.log.splice(0, this.S.log.length - 120);
112:   }
113: 
114:   add(delta) {
115:     const S = this.S;
116:     if (delta.water != null) S.water = clamp(S.water + delta.water, 0, 99);
117:     if (delta.food != null) S.food = clamp(S.food + delta.food, 0, 99);
118:     if (delta.fuel != null) S.fuel = clamp(S.fuel + delta.fuel, 0, 99);
119:     if (delta.scrap != null) S.scrap = clamp(S.scrap + delta.scrap, 0, 9999);
120:     if (delta.meds != null) S.meds = clamp(S.meds + delta.meds, 0, 99);
121:     if (delta.hull != null) S.hull = clamp(S.hull + delta.hull, 0, 100);
122:     if (delta.morale != null) S.morale = clamp(S.morale + delta.morale, 0, 100);
123:     if (delta.mile != null) S.mile = Math.max(0, Math.min(960, S.mile + delta.mile));
124:     if (delta.scrap > 0) S.scrapEarned += delta.scrap;
125:   }
126: 
127:   pay(cost) {
128:     for (const k of Object.keys(cost)) {
129:       if ((this.S[k] || 0) < cost[k]) return false;
130:     }
131:     for (const k of Object.keys(cost)) this.S[k] -= cost[k];
132:     return true;
133:   }
134: 
135:   canAfford(cost) {
136:     return Object.entries(cost).every(([k, v]) => (this.S[k] || 0) >= v);
137:   }
138: 
139:   health(member, amount, status, cause) {
140:     if (!member || !member.alive) return member;
141:     const soften = this.hasTrait('rook') ? 0.88 : 1;
142:     if (amount < 0) amount *= soften;
143:     member.health = clamp(member.health + amount, 0, 100);
144:     if (status && member.health > 0) {
145:       const bad = ['sick', 'injured', 'rad'];
146:       if (bad.includes(status)) member.status = status;
147:     }
148:     if (member.health <= 0) {
149:       member.alive = false;
150:       member.health = 0;
151:       member.status = 'dead';
152:       this.log(`${member.name} is dead. ${cause || pick(['The road took them.', 'There was nothing left to do.', 'It was quick, at least.'])}`, 'bad');
153:     }
154:     return member;
155:   }
156: 
157:   hurt(amount, status = 'injured', member = null) {
158:     const target = member && member.alive ? member : pick(this.alive());
159:     if (!target) return null;
160:     this.health(target, -amount, status);
161:     return target;
162:   }
163: 
164:   hurtAll(amount, status = 'injured') {
165:     for (const p of this.alive()) this.health(p, -amount, status);
166:   }
167: 
168:   heal(amount, member = null) {
169:     const targets = member ? [member] : this.alive();
170:     for (const p of targets) {
171:       if (!p.alive) continue;
172:       const bonus = this.hasTrait('reyes') ? 1.55 : 1;
173:       p.health = clamp(p.health + amount * bonus, 0, 100);
174:       if (p.health > 32) p.status = 'ok';
175:     }
176:   }
177: 
178:   byId(id) { return this.S.party.find((p) => p.id === id); }
179: 
180:   /* ---------- day / weather / travel ---------- */
181: 
182:   rollWeather() {
183:     const prev = this.S.weather;
184:     const table = [
185:       ['clear', 0.34], ['haze', 0.24], ['dust', 0.17], ['storm', 0.07], ['rain', 0.11], ['cold', 0.07],
186:     ];
187:     if (prev === 'dust') { table[2][1] += 0.08; table[3][1] += 0.06; table[0][1] -= 0.06; }
188:     if (prev === 'storm') { table[3][1] = 0; table[1][1] += 0.1; }
189:     if (prev === 'rain') { table[4][1] = 0.02; table[1][1] += 0.08; }
190:     const total = table.reduce((a, b) => a + b[1], 0);
191:     let r = Math.random() * total;
192:     for (const [id, w] of table) {
193:       r -= w;
194:       if (r <= 0) { this.S.weather = id; return id; }
195:     }
196:     this.S.weather = 'clear';
197:     return 'clear';
198:   }
199: 
200:   /** Advances one day. travel=false for chore days and landmark rests. */
201:   advanceDay({ travel }) {
202:     const S = this.S;
203:     const today = S.day;
204:     const alive = this.alive();
205:     const n = alive.length;
206:     if (n === 0) return;
207:     const p = PACES[S.pace];
208:     const r = RATIONS[S.ration];
209:     const w = WEATHERS[S.weather];
210:     const scale = 0.42 + 0.58 * (n / 4);
211:     const messages = [];
212: 
213:     // --- fuel & distance ---
214:     let dist = 0;
215:     let fuelUsed = 0;
216:     if (travel) {
217:       const baseDist = p.dist * w.dist * (0.58 + S.hull * 0.0042) * (S.morale < 30 ? 0.92 : 1) * (this.hasTrait('rook') ? 1.05 : 1);
218:       dist = Math.round(baseDist * (0.93 + Math.random() * 0.14));
219:       const fuelNeed = p.fuel * (1 + (100 - S.hull) * 0.0032);
220:       fuelUsed = Math.min(S.fuel, fuelNeed);
221:       if (fuelUsed < fuelNeed - 0.001) {
222:         dist = Math.round(dist * Math.max(0.12, fuelUsed / fuelNeed));
223:         messages.push({ text: 'The cells run dry before the day does. The Mule rolls on fumes and bad language.', kind: 'warn' });
224:         S.morale = clamp(S.morale - 2, 0, 100);
225:       }
226:       S.fuel = clamp(S.fuel - fuelUsed, 0, 99);
227:       S.mile = Math.min(960, S.mile + dist);
228:       S.stats.miles += dist;
229:     } else {
230:       // idling still sips fuel for heat / lights
231:       S.fuel = clamp(S.fuel - 0.6, 0, 99);
232:     }
233: 
234:     // --- water & food ---
235:     const waterNeed = BASE_USE.water * p.water * w.water * scale * (travel ? 1 : 0.72);
236:     const foodNeed = BASE_USE.food * r.food * scale * (travel ? 1 : 0.92);
237:     const waterHave = S.water;
238:     const foodHave = S.food;
239:     S.water = clamp(S.water - waterNeed, 0, 99);
240:     S.food = clamp(S.food - foodNeed, 0, 99);
241:     const waterGap = Math.max(0, waterNeed - waterHave) / Math.max(0.1, waterNeed);
242:     const foodGap = Math.max(0, foodNeed - foodHave) / Math.max(0.1, foodNeed);
243: 
244:     if (waterGap > 0.02) {
245:       const dmg = 5 + waterGap * 11;
246:       this.hurtAll(dmg);
247:       S.morale = clamp(S.morale - 4 * waterGap, 0, 100);
248:       messages.push({ text: `The canteens are dry. ${waterGap > 0.7 ? 'Everyone is cracking at the lips, seeing spots.' : 'Rationing water down to the last mouthful.'}`, kind: 'bad' });
249:     }
250:     if (foodGap > 0.02) {
251:       const dmg = 3 + foodGap * 7;
252:       this.hurtAll(dmg);
253:       S.morale = clamp(S.morale - 3.5 * foodGap, 0, 100);
254:       messages.push({ text: `${foodGap > 0.7 ? 'Nobody has eaten properly in days.' : 'Rations come up short. Bellies complain louder than the engine.'}`, kind: 'bad' });
255:     }
256: 
257:     // --- status & morale drift ---
258:     for (const m of this.alive()) {
259:       if (m.status === 'sick') this.health(m, -1.3);
260:       else if (m.status === 'injured') this.health(m, -1.1);
261:       else if (m.status === 'rad') this.health(m, -1.6);
262:       else if (waterGap === 0 && foodGap === 0 && r === RATIONS.full && S.morale > 55) this.health(m, 0.5);
263:     }
264:     let morale = r.morale + p.morale;
265:     if (S.weather === 'storm') morale -= 2;
266:     if (S.weather === 'rain') morale -= 0.6;
267:     if (waterGap > 0) morale -= 2;
268:     if (foodGap > 0) morale -= 2;
269:     if (this.alive().some((m) => m.status === 'sick')) morale -= 0.8;
270:     if (this.S.dog) morale += 0.5;
271:     S.morale = clamp(S.morale + morale, 0, 100);
272: 
273:     // --- hull wear ---
274:     if (travel) {
275:       let wear = p.hullWear * (0.22 + w.hazard * 5.2) * (0.7 + Math.random() * 0.7);
276:       if (this.hasTrait('voss')) wear *= 0.78;
277:       if (wear > 0.15) S.hull = clamp(S.hull - wear, 0, 100);
278:       if (S.hull < 46 && chance(0.1 + (46 - S.hull) * 0.008)) {
279:         const dmg = int(2, 7);
280:         S.hull = clamp(S.hull - dmg, 0, 100);
281:         S.stats.damages += 1;
282:         messages.push({ text: `Something under the floorpan lets go. ${this.hasTrait('voss') ? 'Mara hears it first and is already reaching for the torch.' : 'The whole frame shudders.'}`, kind: 'warn' });
283:       }
284:     }
285: 
286:     // --- ambient & summary ---
287:     if (travel) {
288:       messages.unshift({
289:         text: `Mile ${Math.floor(S.mile)}. ${dist} miles today${fuelUsed > 0 ? `, ${fuelUsed.toFixed(1)} fuel burned` : ''}. ${WEATHERS[S.weather].label.toLowerCase()}.`,
290:         kind: 'daybreak',
291:       });
292:       if (chance(0.35)) messages.push({ text: pick(AMBIENT), kind: '' });
293:     }
294: 
295:     S.day += 1;
296:     this.rollWeather();
297: 
298:     // death / end checks
299:     if (this.aliveCount() === 0) {
300:       this.finish(false, 'The last of you stops breathing somewhere on the road. The Mule idles until the fuel runs out.');
301:     } else if (S.hull <= 0) {
302:       this.finish(false, 'The Mule gives out — a sound like a dropped toolbox, then nothing. Without wheels, the miles are just weather.');
303:     }
304: 
305:     return { messages, dist, today, ended: !!S.ended };
306:   }
307: 
308:   logMany(list) {
309:     for (const m of list) this.log(m.text, m.kind);
310:   }
311: 
312:   /* ---------- public turn actions ---------- */
313: 
314:   drive() {
315:     if (this.phase !== 'travel' || !this.S || this.S.ended) return null;
316:     const res = this.advanceDay({ travel: true });
317:     if (!res) return null;
318:     this.logMany(res.messages);
319:     if (this.S.ended) return { messages: res.messages, ended: this.S.ended };
320: 
321:     const arrival = this.checkArrival();
322:     if (arrival) {
323:       this.pendingArrival = arrival;
324:       this.phase = 'arrival';
325:       this.log(`You reach ${arrival.name}.`, 'good');
326:       this.save();
327:       return { messages: res.messages, arrival: this.publicStop(arrival) };
328:     }
329: 
330:     const ev = this.maybeEvent();
331:     if (ev) {
332:       this.pendingEvent = ev;
333:       this.phase = 'event';
334:       this.log(`— ${ev.title} —`, 'event');
335:       this.save();
336:       return { messages: res.messages, event: this.eventView(ev) };
337:     }
338: 
339:     this.save();
340:     return { messages: res.messages };
341:   }
342: 
343:   chore(id) {
344:     if (this.phase !== 'travel' || !this.S || this.S.ended) return null;
345:     const chore = CHORES.find((c) => c.id === id);
346:     if (!chore) return null;
347:     const messages = [];
348:     const S = this.S;
349: 
350:     if (id === 'scavenge') {
351:       if (!this.pay({ water: 1 })) return { blocked: 'You need 1 water for the trip into the ruins.' };
352:       const p = PACES[S.pace];
353:       const loot = Math.round(int(13, 27) * (this.hasTrait('dex') ? 1.35 : 1));
354:       const fuel = int(0, 5);
355:       this.add({ scrap: loot, fuel });
356:       S.stats.scavenged += loot;
357:       messages.push({ text: `You spend the day in a collapsed mall picking copper out of the walls. +${loot} scrap${fuel ? `, +${fuel} fuel` : ''}.`, kind: 'good' });
358:       if (chance(0.33)) {
359:         const water = int(3, 6);
360:         this.add({ water });
361:         messages.push({ text: `A pipe in the ceiling still holds clean water. You fill ${water} units.`, kind: 'good' });
362:       }
363:       if (chance(0.28)) {
364:         const m = this.hurt(int(5, 12));
365:         messages.push({ text: `${m ? m.name : 'Someone'} comes back limping. ${pick(['A floor gave way.', 'Someone else was already living in there.', 'A nail through the boot.'])}`, kind: 'bad' });
366:       }
367:     } else if (id === 'forage') {
368:       const food = int(6, 14) + (this.hasTrait('rook') ? 2 : 0);
369:       const water = int(1, 4);
370:       this.add({ food, water });
371:       S.foodFound += food;
372:       messages.push({ text: `Rook finds a drainage cut with edible weeds and something that used to be a rabbit. +${food} rations, +${water} water.`, kind: 'good' });
373:       if (chance(0.2)) {
374:         const m = this.hurt(int(4, 10));
375:         messages.push({ text: `${m ? m.name : 'Someone'} gets cut open on a snare in the brush.`, kind: 'bad' });
376:       }
377:     } else if (id === 'rest') {
378:       const heal = 9 + (this.hasTrait('reyes') ? 6 : 0);
379:       this.heal(heal);
380:       this.add({ morale: 6 });
381:       messages.push({ text: `You pull off the road and let the engine cool. Everyone sleeps in a pile with the heater on low. The crew looks human again.`, kind: 'good' });
382:     } else if (id === 'repair') {
383:       if (S.hull >= 99) return { blocked: 'The Mule is already as whole as it is ever going to be.' };
384:       if (!this.pay({ scrap: 6 })) return { blocked: 'You need 6 scrap to patch the hull.' };
385:       const patch = 11 + (this.hasTrait('voss') ? 7 : 0);
386:       this.add({ hull: patch });
387:       messages.push({ text: `Mara welds a plate over the worst of it and Dex holds the light. +${patch} hull. ${S.hull > 90 ? '"Good as new," she lies.' : '"It\'ll hold."'}`, kind: 'good' });
388:     } else if (id === 'distill') {
389:       if (!this.pay({ fuel: 3 })) return { blocked: 'You need 3 fuel to run the still.' };
390:       const water = int(11, 17) + (S.weather === 'rain' ? 4 : 0);
391:       this.add({ water });
392:       messages.push({ text: `You run the still off the engine block. It gurgles and spits and gives up ${water} units of water that tastes like hot plastic.`, kind: 'good' });
393:     }
394: 
395:     S.stats.chores += 1;
396:     const res = this.advanceDay({ travel: false });
397:     if (res) messages.unshift(...res.messages);
398:     if (S.ended) { this.logMany(messages); this.save(); return { messages, ended: S.ended }; }
399:     messages.push(...this.choreDrift(id));
400:     this.logMany(messages);
401:     this.save();
402:     return { messages };
403:   }
404: 
405:   choreDrift(id) {
406:     const out = [];
407:     const roll = Math.random();
408:     if (roll < 0.13) {
409:       const m = this.alive()[Math.floor(Math.random() * this.aliveCount())];
410:       if (id === 'scavenge' && chance(0.5)) {
411:         this.add({ scrap: 8 });
412:         out.push({ text: 'On the way back, Dex kicks open a locker with eight more scrap in it. He is insufferable about this.', kind: 'good' });
413:       } else if (m) {
414:         this.health(m, -4, id === 'repair' ? 'injured' : 'sick');
415:         out.push({ text: `${m.name} picks up a cough that settles in for the night.`, kind: 'warn' });
416:       }
417:     }
418:     return out;
419:   }
420: 
421:   /* ---------- events ---------- */
422: 
423:   maybeEvent() {
424:     const S = this.S;
425:     let p = 0.5;
426:     if (S.pace === 'sprint') p += 0.1;
427:     if (S.weather === 'storm') p += 0.08;
428:     if (!chance(p)) return null;
429:     const eligible = EVENTS.filter((e) => {
430:       if (S.recentEvents.includes(e.id)) return false;
431:       if (e.id === 'fever' && this.aliveCount() < 2) return false;
432:       return true;
433:     });
434:     if (!eligible.length) return null;
435:     const total = eligible.reduce((a, e) => a + e.weight, 0);
436:     let r = Math.random() * total;
437:     let chosen = eligible[eligible.length - 1];
438:     for (const e of eligible) {
439:       r -= e.weight;
440:       if (r <= 0) { chosen = e; break; }
441:     }
442:     S.recentEvents.push(chosen.id);
443:     if (S.recentEvents.length > 6) S.recentEvents.shift();
444:     S.stats.events += 1;
445:     return chosen;
446:   }
447: 
448:   eventView(ev) {
449:     const g = this.context();
450:     const text = typeof ev.text === 'function' ? ev.text(g) : ev.text;
451:     const choices = ev.choices.map((c, i) => {
452:       let disabled = null;
453:       if (c.requires) disabled = c.requires(g);
454:       return { i, label: c.label, hint: c.hint, disabled };
455:     });
456:     return { id: ev.id, title: ev.title, kicker: ev.kicker, art: ev.art, text, choices };
457:   }
458: 
459:   context() {
460:     const g = {
461:       s: this.S,
462:       chance, pick, int,
463:       rand: Math.random,
464:       add: (d) => this.add(d),
465:       pay: (c) => this.pay(c),
466:       can: (c) => this.canAfford(c),
467:       hurt: (amt, status = 'injured', member = null) => this.hurt(amt, status, member),
468:       hurtAll: (amt, status) => this.hurtAll(amt, status),
469:       heal: (amt) => this.heal(amt),
470:       pickAlive: () => pick(this.alive()),
471:       alive: () => this.alive(),
472:       byId: (id) => this.byId(id),
473:       log: (t, k) => this.log(t, k),
474:       morale: (n) => this.add({ morale: n }),
475:       hull: (n) => this.add({ hull: n }),
476:       trait: (id) => this.hasTrait(id),
477:     };
478:     return g;
479:   }
480: 
481:   resolveEvent(index) {
482:     if (this.phase !== 'event' || !this.pendingEvent) return null;
483:     const ev = this.pendingEvent;
