350: function guard(fn) {
351:   if (ui.busy) return;
352:   ui.busy = true;
353:   try { fn(); } finally { setTimeout(() => { ui.busy = false; }, 120); }
354: }
355: 
356: function onDrive() {
357:   if (!game.S || game.phase !== 'travel' || game.S.ended) return;
358:   guard(() => {
359:     const res = game.drive();
360:     if (!res) return;
361:     render();
362:     if (res.ended) { showEnding(res.ended); return; }
363:     if (ui.scene) { ui.scene.setSpeed(1.25); setTimeout(() => ui.scene && ui.scene.setSpeed(paceSpeed()), 900); }
364:     sound('drive');
365:     if (res.arrival) { showArrival(res.arrival); return; }
366:     if (res.event) { showEvent(res.event); return; }
367:     if (game.S.ended) showEnding(game.S.ended);
368:   });
369: }
370: 
371: function onChore(id) {
372:   if (!game.S || game.phase !== 'travel' || game.S.ended) return;
373:   guard(() => {
374:     const res = game.chore(id);
375:     if (!res) return;
376:     render();
377:     if (res.blocked) { toast(res.blocked, 'bad'); sound('bad'); return; }
378:     sound(id === 'rest' ? 'good' : 'click');
379:     if (res.ended) { showEnding(res.ended); return; }
380:     if (res.event) { showEvent(res.event); return; }
381:     if (game.S.ended) showEnding(game.S.ended);
382:   });
383: }
