385: function setPace(pace) {
386:   if (!game.S || game.phase !== 'travel') return;
387:   game.S.pace = pace;
388:   render();
389:   sound('click');
390: }
391: 
392: function setRation(ration) {
393:   if (!game.S || game.phase !== 'travel') return;
394:   game.S.ration = ration;
395:   render();
396:   sound('click');
397: }
