399: export function boot() {
400:   ui.muted = loadMuted();
401:   setMuted(ui.muted);
402:   renderStartRoster();
403:   refreshResume();
404:   showStart();
405: 
406:   $('#btn-start').addEventListener('click', () => { ensureAudio(); sound('click'); beginGame(false); });
407:   $('#btn-resume').addEventListener('click', () => { ensureAudio(); sound('click'); beginGame(true); });
408:   $('#btn-sound').addEventListener('click', () => { setMuted(!ui.muted); if (!ui.muted) sound('good'); });
409:   $('#btn-quit').addEventListener('click', () => { sound('click'); showQuit(); });
410:   $('#btn-drive').addEventListener('click', onDrive);
411: 
412:   $('#pace-group').addEventListener('click', (e) => {
413:     const b = e.target.closest('button[data-pace]');
414:     if (b) setPace(b.dataset.pace);
415:   });
416:   $('#ration-group').addEventListener('click', (e) => {
417:     const b = e.target.closest('button[data-ration]');
418:     if (b) setRation(b.dataset.ration);
419:   });
420:   $('#action-grid').addEventListener('click', (e) => {
421:     const b = e.target.closest('button[data-chore]');
422:     if (b && !b.disabled) onChore(b.dataset.chore);
423:   });
424: 
425:   document.addEventListener('keydown', (e) => {
426:     if (e.target.matches('input, textarea')) return;
427:     if (!$('#modal-layer').classList.contains('hidden')) {
428:       if (e.key === 'Enter' || e.key === ' ') {
429:         const primary = $('#modal-card [data-enter]');
430:         if (primary && !primary.disabled) { e.preventDefault(); primary.click(); }
431:       }
432:       return;
433:     }
434:     if ($('#screen-game').classList.contains('hidden')) {
435:       if (e.key === 'Enter') $('#btn-start').click();
436:       return;
437:     }
438:     if (e.code === 'Space') { e.preventDefault(); if (!$('#btn-drive').disabled) onDrive(); }
439:     else if (/^[1-5]$/.test(e.key)) {
440:       const chore = CHORES[Number(e.key) - 1];
441:       if (chore) onChore(chore.id);
442:     }
443:   });
444: 
445:   document.addEventListener('visibilitychange', () => {
446:     if (!ui.scene) return;
447:     if (document.hidden) ui.scene.stop();
448:     else if (!$('#screen-game').classList.contains('hidden')) ui.scene.start();
449:   });
450: 
451:   window.addEventListener('beforeunload', () => { if (game.S && !game.S.ended) game.save(); });
452: 
453:   // test hook (harmless in production)
454:   window.__ASH = { game, render, boot };
455: }
