547: function showEnding(end) {
548:   const winners = end.survivors;
549:   const lost = end.lost;
550:   const n = winners.length;
551:   const victory = end.victory;
552:   let title;
553:   let copy;
554:   if (victory) {
555:     title = n === 4 ? 'All four of you walk in.' : n === 3 ? 'Three of you walk in.' : n === 2 ? 'Two of you walk in.' : n === 1 ? 'One of you walks in.' : 'The gate opens on an empty crawler.';
556:     copy = n === 4
557:       ? 'The guard counts four and steps aside. Behind the fence there is grass, and a woman with a clipboard, and a sky the color of clean water. Nobody says anything for a long time.'
558:       : `The guard counts ${n} and does not ask about the seats that are empty. Eden-9 takes you in. The gate closes behind the Mule, and for the first time in nine hundred miles, nothing is following.`;
559:   } else {
560:     title = 'The road keeps what it takes.';
561:     copy = end.reason || 'Somewhere past the last mile marker, the Mule stops. The dust fills the seats. Eden-9 stays a rumor.';
562:   }
563: 
564:   const crewRows = [
565:     ...winners.map((p) => `<div class="epitaph-row"><div class="av" data-tone="${p.tone}">${p.initials}</div><span>${p.name}</span><span class="why" style="color:var(--green)">made it · ${p.health}hp</span></div>`),
566:     ...lost.map((p) => `<div class="epitaph-row gone"><div class="av" data-tone="${p.tone}">${p.initials}</div><span>${p.name}</span><span class="why">lost</span></div>`),
567:   ].join('');
568: 
569:   openModal(`
570:     <div class="end-flag" style="color:${victory ? 'var(--green)' : 'var(--red)'}">${victory ? '● RUN COMPLETE — EDEN-9' : '● RUN TERMINATED'}</div>
571:     <h3>${title}</h3>
572:     <p class="modal-text">${copy}</p>
573:     <div class="epitaph">${crewRows}</div>
574:     <div class="stats">
575:       <div class="stat-cell"><div class="k">Days</div><div class="v">${end.day}</div></div>
576:       <div class="stat-cell"><div class="k">Miles</div><div class="v">${end.mile}<small>/960</small></div></div>
577:       <div class="stat-cell"><div class="k">Survivors</div><div class="v">${n}<small>/4</small></div></div>
578:       <div class="stat-cell"><div class="k">Score</div><div class="v">${end.score}</div></div>
579:     </div>
580:     <p class="end-note">${victory ? `Grade <strong style="color:var(--amber)">${end.grade}</strong>. ${end.day} days on the road. ${end.events} encounters. ${money(end.loot)} scrap scavenged from the corpse of the world.` : 'The trail is long. Try again with more water and fewer heroics.'}</p>
581:     <div class="modal-actions">
582:       <button class="btn btn-primary" data-act="new-run" data-enter="1">Run it again</button>
583:       <button class="btn" data-act="title">Return to title</button>
584:     </div>
585:   `, 'ending');
586:   sound(victory ? 'win' : 'death');
587: }
