405:   .layout{grid-template-columns:minmax(0,1.15fr) minmax(330px,.85fr)}
406:   .supply-grid{grid-template-columns:repeat(3,1fr)}
407:   .supply:nth-child(n+4){border-top:1px solid var(--line)}
408:   .supply{padding:7px 9px}
409:   .supply-v{font-size:15px}
410:   .brand-sub{display:none}
411: }
412: @media (max-width:860px){
413:   .start-inner{grid-template-columns:1fr;gap:26px}
414:   .start-art{order:-1}
415:   .start-art canvas{aspect-ratio:16/8;max-height:26vh;min-height:150px}
416:   .start-art-caption{display:none}
417:   .roster{max-width:none}
418:   .title{font-size:clamp(56px,15vw,92px)}
419:   .premise{max-width:none;font-size:13.5px}
420:   .start-foot{margin-top:20px}
421:   .game{height:auto;min-height:100dvh;display:block;padding-bottom:calc(10px + env(safe-area-inset-bottom))}
422:   .topbar{position:sticky;top:0;z-index:20;background:rgba(10,9,8,.94);backdrop-filter:blur(8px);padding:8px 2px;margin:0 -2px}
423:   .layout{display:flex;flex-direction:column;gap:8px}
424:   .col-main{overflow:visible;gap:8px}
425:   .scene-wrap{flex:none;aspect-ratio:16/9;min-height:0;max-height:34vh}
426:   .scene-v{font-size:10px}
427:   .supply-grid{grid-template-columns:repeat(3,1fr)}
428:   .crew-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
429:   .log-panel{flex:none;height:184px;min-height:0}
430:   .controls{position:relative}
431:   .actions{grid-template-columns:repeat(5,minmax(0,1fr))}
432:   .actions .action b{font-size:7.4px}
433:   .stat-v{font-size:15px}
434:   .topstat{gap:10px}
435:   .stat-k{font-size:8px}
436:   .btn-small{display:none}
437:   .modal-card{padding:18px 16px 16px;max-height:88vh}
438:   .modal-card h3{font-size:22px}
439:   .choice{padding:11px 12px}
440:   .choice b{font-size:13px}
441:   .stats{grid-template-columns:repeat(2,1fr)}
442:   .start{padding:16px 14px calc(20px + env(safe-area-inset-bottom))}
443:   .roster{grid-template-columns:repeat(2,1fr);gap:6px}
444:   .start-actions .btn{flex:1}
445:   .briefing{max-width:none}
446: }
447: @media (max-width:430px){
448:   body{font-size:14px}
449:   .topbar{gap:6px}
450:   .brand{gap:6px}
451:   .brand-mark{width:29px;height:29px;font-size:9px}
452:   .brand-name{font-size:12.5px;letter-spacing:.1em}
453:   .stat{gap:3px}
454:   .stat-v{font-size:13.5px}
455:   .stat-sub{display:none}
456:   .topstat{gap:7px}
457:   .iconbtn{width:30px;height:30px}
458:   .scene-wrap{aspect-ratio:16/10}
459:   .scene-top{padding:7px 9px}
460:   .scene-bottom{padding:6px 9px 8px}
461:   .scene-weather{padding:3px 7px;font-size:8px}
462:   .supply-grid{grid-template-columns:repeat(3,1fr)}
463:   .crew-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
464:   .log-panel{height:168px}
465:   .entry{grid-template-columns:34px 1fr;font-size:11.4px;gap:7px}
466:   .drive-main{font-size:12px}
467:   .drive-sub{font-size:8px}
468:   .control-note{display:none}
469:   .actions{gap:4px}
470:   .action span{display:none}
471:   .action{padding:8px 1px}
472:   .action b{font-size:7px;letter-spacing:.02em}
473:   .modal-layer{padding:8px;align-items:end}
474:   .modal-card{max-height:92vh;border-radius:14px 14px 10px 10px;padding:18px 14px calc(14px + env(safe-area-inset-bottom))}
475:   .modal-choices .choice b{font-size:12.5px}
476:   .lm-mile{display:none}
477:   .roster-card{padding:7px}
478:   .roster-card b{font-size:11.5px}
479:   .start-art canvas{max-height:22vh;min-height:120px}
480: }
481: @media (max-height:720px) and (min-width:861px){
482:   .scene-wrap{min-height:150px}
483:   .log-panel{min-height:90px}
484:   .controls{gap:6px;padding:8px 10px 9px}
485:   .supply{padding:6px 8px}
486:   .crew{padding:6px 8px}
487:   .brand-sub{display:none}
488: }
489: @media (prefers-reduced-motion:reduce){
490:   *,*::before,*::after{animation-duration:.001ms !important;animation-iteration-count:1 !important;transition-duration:.001ms !important}
491: }
